LIBROSA_DEFAULT_SR = 22050
INT16_SCALE = 32768


def frame_count(num_samples, n_fft, hop, center=True):
    if hop < 1 or n_fft < 1:
        raise ValueError("n_fft and hop must be positive")
    if center:
        return 1 + num_samples // hop
    if num_samples < n_fft:
        return 0
    return 1 + (num_samples - n_fft) // hop


def spectrogram_shape(num_samples, n_fft, hop, center=True):
    return (n_fft // 2 + 1, frame_count(num_samples, n_fft, hop, center))


def normalise_pcm16(samples):
    out = []
    for value in samples:
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("expected integer samples")
        if not -INT16_SCALE <= value <= INT16_SCALE - 1:
            raise ValueError(f"{value} is outside the 16-bit range")
        out.append(value / INT16_SCALE)
    return out


def to_channels_first(array):
    if not array:
        raise ValueError("empty audio")
    if isinstance(array[0], list):
        return [list(channel) for channel in array]
    return [list(array)]


def to_mono(array):
    channels = to_channels_first(array)
    if len(channels) == 1:
        return list(channels[0])
    length = len(channels[0])
    return [sum(channel[index] for channel in channels) / len(channels)
            for index in range(length)]


def load_contract(library, native_sr, channels, sr="unset", mono="unset"):
    if library == "torchaudio":
        return {"sample_rate": native_sr, "channels": channels, "ndim": 2}
    if library != "librosa":
        raise ValueError(f"unknown library {library!r}")
    rate = LIBROSA_DEFAULT_SR if sr == "unset" else (native_sr if sr is None else sr)
    as_mono = True if mono == "unset" else bool(mono)
    return {"sample_rate": rate,
            "channels": 1 if as_mono else channels,
            "ndim": 1 if as_mono else 2}
